/* ---------- confetti + a little fanfare ---------- */
function confetti(ms){let cv=$('confetti');if(!cv){cv=document.createElement('canvas');cv.id='confetti';document.body.appendChild(cv);}const W_=cv.width=innerWidth,H_=cv.height=innerHeight;const x=cv.getContext('2d');cv.hidden=false;
  const cols=['#ff6f61','#ffd166','#4fc3a1','#7aa7ff','#b28dff','#ff9fc6'];const P=[];for(let i=0;i<(A11Y.rm?60:170);i++)P.push({x:W_/2+rr(-80,80),y:H_*0.35,vx:rr(-9,9),vy:rr(-14,-4),r:rr(4,9),c:pick(cols),a:rr(0,TAU),va:rr(-0.3,0.3)});
  const t0=performance.now();const step=now=>{const k=(now-t0)/(ms||2600);x.clearRect(0,0,W_,H_);for(const p of P){p.vy+=0.35;p.vx*=0.99;p.x+=p.vx;p.y+=p.vy;p.a+=p.va;x.save();x.globalAlpha=Math.max(0,1-k*k);x.translate(p.x,p.y);x.rotate(p.a);x.fillStyle=p.c;x.fillRect(-p.r/2,-p.r/4,p.r,p.r/2);x.restore();}if(k<1)requestAnimationFrame(step);else cv.hidden=true;};requestAnimationFrame(step);}
function fanfare(){if(!sfxInit())return;if(AUD.ctx.state!=='running')AUD.ctx.resume();const sav=SFX.out.gain.value;SFX.out.gain.setValueAtTime(0.9,AUD.ctx.currentTime);
  [[523,0],[659,0.12],[784,0.24],[1047,0.38]].forEach(([f,d])=>{tone(f,0.5,0.09,'triangle',null,d);tone(f*2,0.3,0.03,'sine',null,d);});[523,659,784].forEach(f=>tone(f,1.2,0.05,'triangle',null,0.55));tone(2093,0.6,0.04,'sine',null,0.6);tone(2637,0.6,0.03,'sine',null,0.7);}
{const _su=showUnlock;showUnlock=function(d){_su(d);confetti(3200);fanfare();earnBadge('area-'+d.id);};}

