const BMAP={};BADGES.forEach(b=>BMAP[b.id]=b);
let MYBADGES=store.get('badges8',[]);
function badgeCanvas(b,size,locked){const c=document.createElement('canvas');c.width=c.height=size||160;const x=c.getContext('2d');const S=c.width,r=S*0.42;x.translate(S/2,S/2);
  x.fillStyle=locked?'#dfe5ec':'#ffffff';x.beginPath();for(let i=0;i<24;i++){const a=i/24*TAU,rr_=i%2?r:r*1.08;x.lineTo(Math.cos(a)*rr_,Math.sin(a)*rr_);}x.closePath();x.fill();
  x.fillStyle=locked?'#c3ccd6':b.c;x.beginPath();x.arc(0,0,r*0.86,0,TAU);x.fill();x.strokeStyle='rgba(255,255,255,.6)';x.lineWidth=S*0.025;x.beginPath();x.arc(0,0,r*0.72,0,TAU);x.stroke();if(!locked)drawIcon(x,b.i,0,0,r*0.62);else{x.fillStyle='#fff';x.font=`800 ${S*0.3}px ${FD}`;x.textAlign='center';x.textBaseline='middle';x.fillText('?',0,4);}return c;}
function earnBadge(id){const b=BMAP[id];if(!b||MYBADGES.includes(id))return;MYBADGES.push(id);store.set('badges8',MYBADGES);track('badge',{id});syncBadgeBtn();
  const el=document.createElement('div');el.className='badgepop';el.innerHTML=`<div class="bp-art"></div><div><div class="bp-eye">New badge</div><b>${esc(b.n)}</b><span>${esc(b.d)}</span></div>`;el.querySelector('.bp-art').appendChild(badgeCanvas(b,120));document.body.appendChild(el);
  confetti(2400);fanfare();speak(`New badge: ${b.n}. ${b.d}`);setTimeout(()=>el.classList.add('out'),3800);setTimeout(()=>el.remove(),4400);}
function syncBadgeBtn(){const b=$('btnBadges');if(b)b.querySelector('b').textContent=MYBADGES.length;}
function openBadges(){openPanel({title:'Your badges',eyebrow:'Collection',color:'#e0a030',sub:`${MYBADGES.length} of ${BADGES.length} collected. Some are easy, some are hidden in corners of the city.`,build:b=>{
  const g=document.createElement('div');g.className='badgegrid';BADGES.forEach(bd=>{const got=MYBADGES.includes(bd.id);const d=document.createElement('div');d.className='bg-item'+(got?' got':'');d.appendChild(badgeCanvas(bd,120,!got));const t=document.createElement('div');t.innerHTML=`<b>${got?esc(bd.n):'???'}</b><span>${esc(bd.d)}</span>`;d.appendChild(t);g.appendChild(d);});b.appendChild(g);}});}
award=function(n,why,key){if(key){const k=store.get('awarded',{});if(k[key])return;k[key]=1;store.set('awarded',k);}
  const before=levelOf(POINTS)[1];POINTS+=n;store.set('points',POINTS);$('ptsVal').textContent=POINTS;
  const el=document.createElement('div');el.className='ptsfloat';el.innerHTML=`<b>+${n}</b>${esc(why||'')}`;document.body.appendChild(el);setTimeout(()=>el.remove(),2500);
  if(/Focus session done|Study session done/.test(why||''))earnBadge('studybuddy');const after=levelOf(POINTS)[1];if(after!==before)setTimeout(()=>earnBadge('tier-'+after),900);};
(function addBadgeBtn(){const tl=document.querySelector('.hud-tl');const b=document.createElement('button');b.className='side-btn';b.id='btnBadges';b.type='button';b.innerHTML=`<span class="sb-ic"></span>Badges <b>0</b>`;b.querySelector('.sb-ic').appendChild(badgeCanvas(BADGES[0],48));b.addEventListener('click',openBadges);tl.appendChild(b);syncBadgeBtn();})();

/* ---------- a mood check-in you can open from anywhere ---------- */
(function addMoodChip(){const tr=document.querySelector('.hud-tr');const b=document.createElement('button');b.className='chip';b.id='btnMood';b.type='button';b.innerHTML='<span class="mood-dot"></span>Mood';tr.insertBefore(b,$('btnMap'));b.addEventListener('click',openMoodCheck);syncMoodDot();})();
function syncMoodDot(){const h=store.get('moods',[]);const d=document.querySelector('#btnMood .mood-dot');if(d)d.style.background=h.length?h[h.length-1].c:'#c3ccd6';}
function openMoodCheck(){openPanel({title:'How are you, right now?',eyebrow:'Mood check-in',color:'#f2874f',sub:'Pick the closest one. It stays on this device.',build:b=>{
  b.innerHTML=`<div class="moods" id="mq"></div><div id="mqOut"></div><h3 class="h3">Your last check-ins</h3><div class="moodstrip" id="mqH"></div>`;
  const draw=()=>{const h=store.get('moods',[]);b.querySelector('#mqH').innerHTML=h.length?h.slice(-14).map(x=>{const d=new Date(x.t);return `<div><i style="background:${x.c}"></i><b>${esc(x.k)}</b><span>${d.toLocaleDateString(undefined,{weekday:'short'})} ${d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</span></div>`;}).reverse().join(''):'<p class="meta">Nothing yet. Your check-ins will line up here, so you can spot patterns.</p>';syncMoodDot();};
  MOODS.forEach(m=>{const x=document.createElement('button');x.type='button';x.innerHTML=`<span aria-hidden="true">${m.e}</span>${m.k}`;x.addEventListener('click',()=>{const h=store.get('moods',[]);h.push({k:m.k,c:m.c,t:Date.now()});store.set('moods',h.slice(-30));track('mood',{id:m.k});award(3,'Mood check-in','mood-'+new Date().toDateString());
    b.querySelector('#mqOut').innerHTML=`<p class="lead" style="margin-top:12px">Noted: <b>${esc(m.k)}</b>. ${m.k==='Happy'||m.k==='Calm'?'Nice.':'Thanks for being honest about it.'} The Mood Café makes a drink to match, if you fancy one.</p>`;draw();});b.querySelector('#mq').appendChild(x);});draw();}});}
{const _co=cafeOrder;cafeOrder=function(){_co();setTimeout(syncMoodDot,200);};}

