/* ---------- Stretch Lawn: frisbee, giant bubbles, hopscotch ---------- */
function buildLawnFun(){const z=Z.yoga;
  /* frisbee with Kabir */
  const KX=z.x-14,KZ=z.z-10;const kab=staticNPC(KX,KZ,0,{shirt:'#2f80d1',pack:false},null,"Frisbee? I throw, you catch. I'm only a little bit competitive.");
  const disc=cyl(0.28,0.28,0.05,'#ff6f61',KX,1.2,KZ,null,18,false);disc.visible=false;
  const F={on:false,t:0,streak:0,best:store.get('frisbeeBest',0),fly:null};
  updaters.push((dt,t)=>{kab.rotation.y=Math.atan2(player.x-KX,player.z-KZ);if(!F.fly)return;const f=F.fly;f.t+=dt;const k=Math.min(1,f.t/f.dur);disc.position.set(f.a.x+(f.b.x-f.a.x)*k+Math.sin(k*Math.PI)*f.curve,1.3+Math.sin(k*Math.PI)*f.h,f.a.z+(f.b.z-f.a.z)*k);disc.rotation.y+=dt*20;
    if(F.mk)F.mk.style.left=(k*100)+'%';if(k>=1&&!f.done){f.done=true;F.result(false);}});
  const throwIt=()=>{const a={x:KX,z:KZ},b={x:player.x,z:player.z};disc.visible=true;F.fly={a,b,t:0,dur:rr(1.4,2.0),h:rr(0.6,2),curve:rr(-2,2),done:false};kab.userData.arms[1].rotation.x=-1.6;setTimeout(()=>kab.userData.arms[1].rotation.x=0,300);};
  const catchIt=()=>{if(!F.fly||F.fly.done)return;const k=F.fly.t/F.fly.dur;F.fly.done=true;const ok=k>0.78&&k<0.98;F.result(ok);};
  SPOTS.push({label:'Play frisbee with Kabir',sub:'Catch it when it reaches you',color:'#2f80d1',tx:KX+3,tz:KZ+5,tr:5,run:()=>{const sp={x:KX+3.5,z:KZ+7.5};player.x=sp.x;player.z=sp.z;player.rot=Math.atan2(KX-sp.x,KZ-sp.z);cam.yaw=player.rot+Math.PI;F.streak=0;
    openPanel({dock:true,title:'Frisbee',eyebrow:'Stretch Lawn',color:'#2f80d1',sub:'Kabir throws. You catch.',build:b=>{b.innerHTML=`<p class="lead">Press <b>Catch</b> (or Space) just as the frisbee reaches you, when the marker hits the green.</p><div class="aim"><span class="aim-g" style="left:78%;width:20%"></span><i id="frM"></i></div><div class="row"><button class="btn primary big" type="button" id="frC">Catch!</button><span class="meta" id="frS">Streak 0 · best ${F.best}</span></div><p class="mindful" id="frT">Kabir: "Ready?"</p><div class="row"><button class="btn ghost" type="button" id="frX">Done</button></div>`;
      F.mk=b.querySelector('#frM');F.result=ok=>{if(ok){F.streak++;disc.visible=false;F.fly=null;if(SFX.ready)tone(880,0.15,0.06,'triangle');if(F.streak>F.best){F.best=F.streak;store.set('frisbeeBest',F.best);}if(F.streak>=5)earnBadge('frisbee');if(F.streak>=3)done('yoga');}else{F.streak=0;if(SFX.ready)burst(300,'lowpass',0.2,0.08);F.fly=null;disc.visible=false;}
        b.querySelector('#frS').textContent=`Streak ${F.streak} · best ${F.best}`;b.querySelector('#frT').textContent=ok?`Kabir: "${pick(['Nice!','Clean catch.','Show-off.','Okay, okay, you\'re good.'])}"`:`Kabir: "${pick(['So close.','My bad, bad throw.','Again!','The wind did that.'])}"`;setTimeout(()=>{if(panelOpen&&F.result)throwIt();},1100);};
      b.querySelector('#frC').addEventListener('click',catchIt);b.querySelector('#frX').addEventListener('click',closePanel);const kd=e=>{if(e.code==='Space'){e.preventDefault();catchIt();}};addEventListener('keydown',kd);setTimeout(throwIt,900);track('activity',{id:'frisbee'});
      return ()=>{removeEventListener('keydown',kd);F.result=null;F.fly=null;disc.visible=false;F.mk=null;};}});
    startAction({x:player.x,z:player.z,rot:player.rot,pose:t=>{resetPose(avatar);idleAnim(avatar,t);avatar.userData.arms.forEach(a=>a.rotation.x=-0.6);},camOff:Math.PI+0.5,dist:7,pitch:0.25});}});
  /* giant bubbles */
  const BX=z.x-11,BZ=z.z+6;const bucket=cyl(0.4,0.35,0.5,'#7aa7ff',BX,0.25,BZ,null,14);addCircle(BX,BZ,0.5);box(0.06,1.2,0.06,'#ffd166',BX+0.2,0.7,BZ,null,false);
  const bubbles=[];const bm=()=>new THREE.MeshStandardMaterial({color:pick(['#ffd6ff','#c9f1ff','#fff2b3','#d6ffe8']),transparent:true,opacity:0.42,roughness:0.05,metalness:0.1,emissive:'#ffffff',emissiveIntensity:0.12});
  updaters.push((dt,t)=>{for(let i=bubbles.length-1;i>=0;i--){const q=bubbles[i];q.t+=dt;q.m.position.x+=q.vx*dt;q.m.position.z+=q.vz*dt;q.m.position.y+=q.vy*dt;q.m.scale.setScalar(q.s*(1+Math.sin(t*3+q.ph)*0.04));if(q.t>12){scene.remove(q.m);bubbles.splice(i,1);}}});
  let pops=0;const blow=()=>{const h=handPos();for(let i=0;i<3;i++){const s=rr(0.4,1.1);const m=new THREE.Mesh(new THREE.SphereGeometry(1,20,16),bm());m.position.set(h.x+rr(-0.3,0.3),h.y+0.3,h.z+rr(-0.3,0.3));m.scale.setScalar(s);scene.add(m);bubbles.push({m,s,t:0,ph:rnd()*TAU,vx:Math.sin(player.rot)*rr(0.6,1.4)+rr(-0.4,0.4),vz:Math.cos(player.rot)*rr(0.6,1.4)+rr(-0.4,0.4),vy:rr(0.15,0.5)});}player.gest='reach';player.gestT=player.gestD=0.6;if(SFX.ready)burst(1200,'lowpass',0.5,0.04,0.5);};
  const popAt=ray=>{const hits=ray.intersectObjects(bubbles.map(q=>q.m),false);if(!hits.length)return false;const q=bubbles.find(o=>o.m===hits[0].object);scene.remove(q.m);bubbles.splice(bubbles.indexOf(q),1);pops++;popSound(400+Math.random()*400);if(pops>=10)done('yoga');return true;};
  MAIN.onClick=r=>W===MAIN&&bubbles.length?popAt(r):false;
  SPOTS.push({label:'Blow giant bubbles',sub:'Click them to pop',color:'#7aa7ff',tx:BX,tz:BZ,tr:3.6,run:()=>{openPanel({dock:true,title:'Giant bubbles',eyebrow:'Stretch Lawn',color:'#7aa7ff',sub:'Blow, watch, pop. Repeat.',build:b=>{b.innerHTML=`<p class="lead">Press <b>Blow</b> (or Space). Click any bubble to pop it.</p><div class="row"><button class="btn primary big" type="button" id="bbB">Blow</button><button class="btn ghost" type="button" id="bbX">Done</button></div><p class="meta" id="bbN"></p>`;
      const kd=e=>{if(e.code==='Space'){e.preventDefault();blow();}};addEventListener('keydown',kd);b.querySelector('#bbB').addEventListener('click',blow);b.querySelector('#bbX').addEventListener('click',closePanel);const iv=setInterval(()=>{b.querySelector('#bbN').textContent=`${pops} popped`;},300);track('activity',{id:'bubbles'});return ()=>{removeEventListener('keydown',kd);clearInterval(iv);};}});
    startAction({x:BX+1.2,z:BZ+1.2,rot:player.rot,pose:t=>{resetPose(avatar);idleAnim(avatar,t);avatar.userData.arms[1].rotation.x=-1.2;},camOff:Math.PI+0.7,dist:8,pitch:0.3});blow();}});
  /* hopscotch */
  const HX=-17,HZ=61.5;KEEP.push([HX+2.6,HZ,4]);const hg=grp(HX,HZ,Math.PI/2);{const pv=new THREE.Mesh(new THREE.PlaneGeometry(2.6,7),LM('#55616f',3));pv.rotation.x=-Math.PI/2;pv.position.set(0,0.035,2.6);pv.receiveShadow=true;hg.add(pv);}const SQ=[[0,0],[0,1],[-0.55,2],[0.55,2],[0,3],[-0.55,4],[0.55,4],[0,5]];
  const ct=cardTex(128,128,(x)=>{x.fillStyle='rgba(0,0,0,0)';x.clearRect(0,0,128,128);x.strokeStyle='#ffe066';x.lineWidth=9;x.strokeRect(6,6,116,116);});
  SQ.forEach(([sx,sz],i)=>{const m=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:ct,transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(sx,0.07,sz*1.05);m.renderOrder=3;hg.add(m);const n=pillSprite(String(i+1),null,0.32,{fs:40,plain:true,bg:'rgba(0,0,0,0)',fg:'#ffffff'});n.position.set(sx,0.1,sz*1.05);hg.add(n);});
  const H={on:false,i:-1,stone:-1};const stoneM=sph(0.12,'#8a8f96',0,0.08,0,hg,6);stoneM.visible=false;
  const sqW=i=>L2W(hg,SQ[i][0],SQ[i][1]*1.05);
  const hop=()=>{if(!H.on||player.action&&player.action.hopping)return;let n=H.i+1;if(n===H.stone)n++;if(n>=SQ.length){H.on=false;toast(pick(['Made it to the end!','Hopscotch champion.','Not a single wobble.']),2400);done('yoga');award(5,'Hopscotch');closePanel();return;}
    const a={x:player.x,z:player.z},b=sqW(n);const t0=performance.now();H.i=n;if(SFX.ready)burst(250,'lowpass',0.12,0.1);
    startAction({hopping:true,lock:true,pose:t=>{resetPose(avatar);const u=avatar.userData;u.legs[1].rotation.x=-1.1;u.arms.forEach(x=>x.rotation.z=x.position.x<0?-0.6:0.6);},follow:()=>{const k=Math.min(1,(performance.now()-t0)/350);player.x=a.x+(b.x-a.x)*k;player.z=a.z+(b.z-a.z)*k;player.y=Math.sin(k*Math.PI)*0.6;player.rot=hg.rotation.y;if(k>=1&&player.action&&player.action.hopping){const ac=player.action;ac.exit=null;player.action=null;resetPose(avatar);player.y=0;}},camOff:Math.PI+0.6,dist:7,pitch:0.35});};
  SPOTS.push({label:'Play hopscotch',sub:'Toss a stone, hop over it',color:'#ffd166',tx:HX,tz:HZ,tr:3.4,run:()=>{H.on=true;H.i=-1;H.stone=1+Math.floor(Math.random()*6);const s=sqW(H.stone);stoneM.visible=true;stoneM.position.set(SQ[H.stone][0],0.08,SQ[H.stone][1]*1.05);const st=L2W(hg,0,-1.3);player.x=st.x;player.z=st.z;player.rot=hg.rotation.y;cam.yaw=player.rot+Math.PI;
    openPanel({dock:true,title:'Hopscotch',eyebrow:'Stretch Lawn',color:'#ffd166',sub:'The stone landed on a square. Don\'t step on that one.',build:b=>{b.innerHTML=`<p class="lead">Press <b>Hop</b> (or Space) to hop to the next square. You'll skip the square with the stone automatically.</p><div class="row"><button class="btn primary big" type="button" id="hsH">Hop!</button><button class="btn ghost" type="button" id="hsX">Done</button></div>`;
      const kd=e=>{if(e.code==='Space'){e.preventDefault();hop();}};addEventListener('keydown',kd);b.querySelector('#hsH').addEventListener('click',hop);b.querySelector('#hsX').addEventListener('click',closePanel);track('activity',{id:'hopscotch'});return ()=>{removeEventListener('keydown',kd);H.on=false;stoneM.visible=false;};}});}});}

/* ---------- museum: illustrated portraits + pop-ups in the middle of the screen ---------- */
const LOOKS={'Wilhelm Wundt':{hair:'#d9d9d9',beard:'full',bald:true,suit:'#3a3f4a',skin:'#f1c7a5'},'William James':{hair:'#6b4a2e',beard:'full',suit:'#5a4632',skin:'#f1c7a5'},'Girindrasekhar Bose':{hair:'#1b1513',mous:true,glasses:true,suit:'#f2efe8',skin:'#b5774c'},'Carl Rogers':{hair:'#9a9da3',bald:true,glasses:true,suit:'#56657d',skin:'#f1c7a5',smile:true},
 'Mary Ainsworth':{hair:'#c9ced6',short:true,suit:'#7c6a58',skin:'#f1c7a5',woman:true},'Aaron T. Beck':{hair:'#ffffff',bow:true,glasses:true,suit:'#3f4f6b',skin:'#f1c7a5',smile:true},'M. Sarada Menon':{hair:'#d9d9d9',bun:true,glasses:true,sari:'#c76b80',skin:'#a4693f',woman:true,smile:true}};
function portraitTex(it,col){return cardTex(256,320,(x,W_,H_)=>{const L=LOOKS[it.title]||{hair:'#3a281c',suit:'#56657d',skin:'#c68a5e'};const g=x.createLinearGradient(0,0,0,H_);g.addColorStop(0,'#fff6ea');g.addColorStop(1,'#f0e2cc');x.fillStyle=g;x.fillRect(0,0,W_,H_);
  x.fillStyle=col;x.globalAlpha=0.25;x.beginPath();x.arc(W_/2,130,100,0,TAU);x.fill();x.globalAlpha=1;
  /* shoulders */
  x.fillStyle=L.sari||L.suit;x.beginPath();x.ellipse(W_/2,H_+10,108,92,0,Math.PI,TAU);x.fill();if(!L.sari&&!L.woman){x.fillStyle='#ffffff';x.beginPath();x.moveTo(W_/2-24,H_-80);x.lineTo(W_/2,H_-40);x.lineTo(W_/2+24,H_-80);x.fill();}if(L.sari){x.fillStyle='#ffd166';x.fillRect(W_/2-90,H_-62,180,8);}
  if(L.bow){x.fillStyle='#c0563f';x.beginPath();x.moveTo(W_/2,H_-70);x.lineTo(W_/2-20,H_-80);x.lineTo(W_/2-20,H_-60);x.closePath();x.moveTo(W_/2,H_-70);x.lineTo(W_/2+20,H_-80);x.lineTo(W_/2+20,H_-60);x.closePath();x.fill();}
  /* neck, face */
  x.fillStyle=L.skin;x.fillRect(W_/2-16,H_-112,32,40);x.beginPath();x.ellipse(W_/2,140,54,66,0,0,TAU);x.fill();
  x.fillStyle=L.hair;if(L.bald){x.beginPath();x.ellipse(W_/2-50,128,10,28,0,0,TAU);x.ellipse(W_/2+50,128,10,28,0,0,TAU);x.fill();}else if(L.bun){x.beginPath();x.ellipse(W_/2,98,56,34,0,Math.PI,TAU);x.fill();x.beginPath();x.arc(W_/2,66,22,0,TAU);x.fill();}else{x.beginPath();x.ellipse(W_/2,96,58,L.short?36:40,0,Math.PI*0.95,TAU+0.05);x.fill();if(L.short){x.beginPath();x.ellipse(W_/2-50,118,12,26,0,0,TAU);x.ellipse(W_/2+50,118,12,26,0,0,TAU);x.fill();}}
  if(L.beard){x.fillStyle=L.hair;x.beginPath();x.ellipse(W_/2,180,46,40,0,0,Math.PI);x.fill();x.fillRect(W_/2-46,160,92,22);}
  if(L.mous||L.beard){x.fillStyle=L.hair;x.beginPath();x.ellipse(W_/2,166,18,6,0,0,TAU);x.fill();}
  x.fillStyle='#2b2b30';x.beginPath();x.arc(W_/2-18,132,4.5,0,TAU);x.arc(W_/2+18,132,4.5,0,TAU);x.fill();
  if(L.glasses){x.strokeStyle='#2b2b30';x.lineWidth=3;x.beginPath();x.arc(W_/2-18,132,12,0,TAU);x.stroke();x.beginPath();x.arc(W_/2+18,132,12,0,TAU);x.stroke();x.beginPath();x.moveTo(W_/2-6,132);x.lineTo(W_/2+6,132);x.stroke();}
  if(!L.beard){x.strokeStyle='#7a3b2a';x.lineWidth=3;x.beginPath();x.arc(W_/2,158,L.smile?14:10,0.25,Math.PI-0.25);x.stroke();}
  x.fillStyle='rgba(0,0,0,.35)';x.font=`600 12px ${FB}`;x.textAlign='right';x.fillText('illustration',W_-10,H_-8);});}
openReading=function(item,sec){const key='mus-'+sec.title+'-'+item.title;stampId('museum');const isP=sec===MUSEUM.people;
  openPanel({title:item.title,eyebrow:sec.title,color:sec.color,sub:item.year,build:b=>{b.innerHTML=`<div class="exhibit-card">${isP?'<div class="ex-portrait"></div>':''}<div><p class="exhibit-year">${esc(item.year)}</p><p class="ex-body">${esc(item.body)}</p><p class="src">A short summary for learning.${isP?' The portrait is an illustration, not a photograph.':''}</p></div></div><div class="row"><button class="btn" type="button" id="exL">Read it to me</button><button class="btn primary" type="button" id="exC">Keep exploring</button></div>`;
    if(isP){const c=portraitTex(item,sec.color).image;c.className='ex-img';b.querySelector('.ex-portrait').appendChild(c);}
    b.querySelector('#exL').addEventListener('click',()=>speak(`${item.title}. ${item.year}. ${item.body}`,true));b.querySelector('#exC').addEventListener('click',closePanel);}});
  award(3,'Learned something new',key);const n=(store.get('musReads',0))+1;store.set('musReads',n);track('activity',{id:'museum-read'});if(n>=2)done('museum');};

/* ---------- a 3D brain you can spin and tap ---------- */
const BRAIN_INFO={frontal:['Frontal lobe','#ff7f95','Right behind your forehead, and the biggest of the four lobes. It is busy with planning, decisions, focus, movement and how you get along with people. Its front part, the prefrontal cortex, keeps developing into your mid-twenties, so learning to manage big feelings really is a work in progress at your age.'],
 parietal:['Parietal lobe','#ffb347','On top, towards the back. It pulls together touch, temperature and pain, and keeps track of where your body is in space. It is the reason you can find your mouth with a spoon in the dark.'],
 temporal:['Temporal lobe','#4fc3a1','Low on each side, near your ears. It handles sounds and language, and helps you recognise faces and store memories. Two important structures, the hippocampus and the amygdala, are tucked inside it.'],
 occipital:['Occipital lobe','#7aa7ff','Right at the back of your head. It turns signals from your eyes into the shapes, colours and movement you see.'],
 cerebellum:['Cerebellum','#b28dff','The wrinkly bit at the lower back. It fine-tunes balance and smooth movement, like riding a bike or typing without looking.'],
 stem:['Brainstem','#9aa1a8','The stalk that links the brain to the spinal cord. It runs the things you never think about: breathing, heartbeat, swallowing and when you feel sleepy or awake.'],
 amygdala:['Amygdala','#e2504f','A small almond-shaped cluster deep in each temporal lobe. It reacts fast to anything that seems threatening and kicks off the fight-or-flight response. Slow breathing and naming your feelings can help calm it down.'],
 hippocampus:['Hippocampus','#2fa39a','A curved structure deep in each temporal lobe, named after the Greek word for seahorse because of its shape. It helps turn today\'s experiences into long-term memories, and good sleep helps it do that job.']};
function openBrain(){let ov=$('brainOv');if(!ov){ov=document.createElement('div');ov.id='brainOv';ov.innerHTML=`<div class="br-card"><button class="bk-x" type="button" aria-label="Close">×</button><div class="br-view"><canvas id="brCv"></canvas><div class="br-hint">Drag to spin · tap a part</div></div><div class="br-side"><div class="eyebrow">Brain model</div><h2 id="brT">Tap any part</h2><p id="brD">Each colour is a different part of the brain. Spin it around and tap one to see what it does.</p><label class="chk" style="margin-top:8px"><input type="checkbox" id="brIn"> See inside (amygdala and hippocampus)</label></div></div>`;document.body.appendChild(ov);}
  ov.hidden=false;const cv=$('brCv');const R=new THREE.WebGLRenderer({canvas:cv,antialias:true,alpha:true});const sz=()=>{const r=cv.parentElement.getBoundingClientRect();R.setSize(r.width,r.height,false);cam2.aspect=r.width/r.height;cam2.updateProjectionMatrix();};
  const sc=new THREE.Scene();const cam2=new THREE.PerspectiveCamera(40,1,0.1,50);cam2.position.set(0,0.4,6.2);cam2.lookAt(0,0,0);sc.add(new THREE.HemisphereLight('#ffffff','#b0a090',0.9));const dl=new THREE.DirectionalLight('#ffffff',0.6);dl.position.set(3,4,5);sc.add(dl);
  const brain=new THREE.Group();sc.add(brain);const parts=[];
  const hemi=(side)=>{const geo=new THREE.SphereGeometry(1,72,56);const pos=geo.attributes.position;const col=new Float32Array(pos.count*3);const reg=new Array(pos.count);const v=new THREE.Vector3();
    for(let i=0;i<pos.count;i++){v.fromBufferAttribute(pos,i);let x=v.x,y=v.y,z=v.z;if(side*x<0)x*=0.15;const fold=0.045*Math.sin(9*x+3*y)*Math.cos(8*z+2*y)+0.03*Math.sin(15*z+x*5);const k=1+fold;x=x*0.72*k+side*0.06;y=y*0.8*k;z=z*1.12*k;if(y<-0.45)y=-0.45+(y+0.45)*0.4;pos.setXYZ(i,x,y,z);
      let r='parietal';if(z>0.42)r='frontal';else if(z<-0.62)r='occipital';else if(y<-0.05&&Math.abs(x)>0.35&&z>-0.55)r='temporal';reg[i]=r;const c=new THREE.Color(BRAIN_INFO[r][1]).lerp(new THREE.Color('#ffffff'),0.15+fold*3);col[i*3]=c.r;col[i*3+1]=c.g;col[i*3+2]=c.b;}
    geo.setAttribute('color',new THREE.BufferAttribute(col,3));geo.computeVertexNormals();const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:0.6,transparent:true,opacity:1}));m.userData.reg=reg;brain.add(m);parts.push(m);return m;};
  const L=hemi(-1),Rh=hemi(1);
  const cb=new THREE.Mesh(new THREE.SphereGeometry(0.42,32,24),new THREE.MeshStandardMaterial({color:'#b28dff',roughness:0.7}));cb.scale.set(1.5,0.7,0.9);cb.position.set(0,-0.48,-0.78);cb.userData.part='cerebellum';brain.add(cb);parts.push(cb);
  for(let i=0;i<6;i++){const t=new THREE.Mesh(new THREE.TorusGeometry(0.5-i*0.02,0.012,6,32,Math.PI),new THREE.MeshBasicMaterial({color:'#9a7ad8'}));t.position.set(0,-0.45-i*0.04,-0.78);t.scale.set(1.25,0.5,1);brain.add(t);}
  const st=new THREE.Mesh(new THREE.CylinderGeometry(0.16,0.12,0.9,16),new THREE.MeshStandardMaterial({color:'#9aa1a8'}));st.position.set(0,-0.85,-0.35);st.rotation.x=0.3;st.userData.part='stem';brain.add(st);parts.push(st);
  const inner=[];for(const sx of [-1,1]){const a=new THREE.Mesh(new THREE.SphereGeometry(0.1,16,12),new THREE.MeshStandardMaterial({color:'#e2504f',emissive:'#e2504f',emissiveIntensity:0.4}));a.position.set(sx*0.42,-0.3,0.12);a.userData.part='amygdala';a.visible=false;brain.add(a);inner.push(a);parts.push(a);
    const h=new THREE.Mesh(new THREE.TorusGeometry(0.18,0.05,8,20,Math.PI*1.2),new THREE.MeshStandardMaterial({color:'#2fa39a',emissive:'#2fa39a',emissiveIntensity:0.4}));h.position.set(sx*0.4,-0.25,-0.18);h.rotation.y=Math.PI/2;h.userData.part='hippocampus';h.visible=false;brain.add(h);inner.push(h);parts.push(h);}
  brain.rotation.set(0.15,-0.7,0);let drag=null,auto=true,raf=0;const ray=new THREE.Raycaster();
  const show=k=>{const I=BRAIN_INFO[k];$('brT').textContent=I[0];$('brT').style.color=I[1];$('brD').textContent=I[2];speak(`${I[0]}. ${I[2]}`);if(SFX.ready)tone(700,0.12,0.04,'sine');track('activity',{id:'brain-'+k});};
  cv.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,m:0};auto=false;cv.setPointerCapture(e.pointerId);};
  cv.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.m+=Math.abs(dx)+Math.abs(dy);drag.x=e.clientX;drag.y=e.clientY;brain.rotation.y+=dx*0.01;brain.rotation.x=clamp(brain.rotation.x+dy*0.01,-1.2,1.2);};
  cv.onpointerup=e=>{const moved=drag&&drag.m>6;drag=null;if(moved)return;const r=cv.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),cam2);const hit=ray.intersectObjects(parts.filter(p=>p.visible),false)[0];if(!hit)return;
    if(hit.object.userData.part)show(hit.object.userData.part);else show(hit.object.userData.reg[hit.face.a]);};
  $('brIn').checked=false;$('brIn').onchange=e=>{const on=e.target.checked;[L,Rh].forEach(m=>{m.material.opacity=on?0.25:1;m.material.depthWrite=!on;});inner.forEach(m=>m.visible=on);if(on)show('hippocampus');};
  const loop2=()=>{if(auto)brain.rotation.y+=0.004;R.render(sc,cam2);raf=requestAnimationFrame(loop2);};sz();loop2();addEventListener('resize',sz);
  const close=()=>{cancelAnimationFrame(raf);removeEventListener('resize',sz);R.dispose();ov.hidden=true;canvas.focus({preventScroll:true});};ov.querySelector('.bk-x').onclick=close;ov.onpointerdown=e=>{if(e.target===ov)close();};
  const kd=e=>{if(e.key==='Escape'&&!ov.hidden){e.stopPropagation();close();removeEventListener('keydown',kd,true);}};addEventListener('keydown',kd,true);
  award(3,'Explored the brain model','brainmodel');done('museum');}

/* ---------- Policy Circle: quick polls, tailored questions, a discussion wall ---------- */
const POLICY_Q={
 mhca:{poll:[['Did you know you have a legal right to mental health care?',['Yes, I knew','No, this is new','Sort of']]],ask:'Has your college ever told students about this right? How could they make it known?'},
 rpwd:{poll:[['Does your college offer adjustments (like extra time or flexible deadlines) to students who need them?',['Yes','No','Not sure']]],ask:'Which adjustment would make the biggest difference for students you know?'},
 nmhp:{poll:[['Do you know of a mental health service near your home or campus?',['Yes','No','Not sure']]],ask:'If you needed help close to home, where would you look first?'},
 nmhpol:{poll:[['How often do you hear people make fun of mental health on campus?',['Often','Sometimes','Rarely']]],ask:'What\'s one thing that would make talking about mental health feel normal at your college?'},
 telemanas:{poll:[['Before today, had you heard of Tele-MANAS (14416)?',['Yes','No']]],ask:'Where should this number be shown so students actually see it?'},
 manodarpan:{poll:[['Has your school or college ever mentioned Manodarpan?',['Yes','No','Not sure']]],ask:'If you called a student helpline, what would you want it to be like?'},
 sc2025:{poll:[['Does your college have a counsellor?',['Yes','No','Not sure']],['How easy is it to approach them?',['Easy','Okay','Hard','Never tried']]],ask:'What would make it easier to walk into the counsellor\'s room?'}};
async function policyItems(){const all=await dbAll('policy');const items=(all||[]).slice();store.get('policyLocal',[]).forEach(x=>{if(!items.some(y=>y.t===x.t&&(y.text===x.text||y.a===x.a)))items.push(x);});return items;}
openPolicy=function(p){stampId('policy');done('policy');const Q=POLICY_Q[p.id]||{poll:[],ask:'What would make this work better for students?'};
  openPanel({wide:true,title:p.name,eyebrow:`Policy Circle · ${p.year}`,color:p.color,sub:'What it says, what you think, and what others think.',build:b=>{
  b.innerHTML=`<div class="pol-grid"><div><h3 class="h3" style="margin-top:0">What it says</h3><ul class="ticks">${p.what.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p class="lead"><b>For students:</b> ${esc(p.students)}</p><p class="src">A short summary for learning, not legal advice. The official text of the law has the full details.</p>
    <h3 class="h3">Quick poll</h3><div id="plPolls"></div></div>
    <div><div class="voice"><b>Your view matters.</b> Write what you really think. No names are shown, there are no wrong answers, and the YMH team reads every response when working on policy suggestions.</div>
    <label class="lbl" for="plS">${esc(Q.ask)}</label><textarea id="plS" rows="3" maxlength="400" placeholder="Write freely…"></textarea><p class="err" id="plE" hidden></p><div class="row" style="margin-top:8px"><button class="btn primary" type="button" id="plGo">Post to the wall</button></div>
    <h3 class="h3">The discussion wall <span class="meta" id="plCount"></span></h3><div class="wall" id="plWall"><p class="meta">Loading…</p></div>
    <p class="store-note">Where this goes: polls and posts are saved anonymously in YMH City's shared database. Everyone who visits can see the wall and the poll results. The YMH team can download all responses.</p></div></div>`;
  const myVotes=store.get('polVotes',{});const pollsEl=b.querySelector('#plPolls');
  const render=async()=>{const items=await policyItems();const mine=items.filter(x=>x.act===p.id);
    pollsEl.innerHTML='';Q.poll.forEach(([q,opts],qi)=>{const votes=mine.filter(x=>x.kind==='poll'&&x.q===qi);const tot=votes.length;const key=p.id+'-'+qi;const d=document.createElement('div');d.className='poll';d.innerHTML=`<p class="poll-q">${esc(q)}</p>`;
      opts.forEach((o,oi)=>{const n=votes.filter(v=>v.a===oi).length;const pct=tot?Math.round(n/tot*100):0;const btn=document.createElement('button');btn.type='button';btn.className='poll-o'+(myVotes[key]===oi?' mine':'');btn.innerHTML=`<i style="width:${myVotes[key]!==undefined?pct:0}%;background:${p.color}"></i><span>${esc(o)}</span><b>${myVotes[key]!==undefined?pct+'%':''}</b>`;btn.disabled=myVotes[key]!==undefined;
        btn.addEventListener('click',async()=>{myVotes[key]=oi;store.set('polVotes',myVotes);const item={act:p.id,kind:'poll',q:qi,a:oi,t:Date.now()};try{await dbAppend('policy',item,80);}catch(e){localAppend('policyLocal',item);}track('policy_poll',{id:p.id});render();});d.appendChild(btn);});
      if(myVotes[key]!==undefined){const m=document.createElement('p');m.className='meta';m.textContent=`${tot} answer${tot===1?'':'s'} so far`;d.appendChild(m);}pollsEl.appendChild(d);});
    const notes=mine.filter(x=>!x.kind||x.kind==='note');const agrees=mine.filter(x=>x.kind==='agree');const cnt=id=>agrees.filter(a=>a.ref===id).length;const myAgree=store.get('polAgree',[]);
    notes.sort((a,c)=>cnt(c.id||c.t)-cnt(a.id||a.t)||c.t-a.t);b.querySelector('#plCount').textContent=notes.length?`· ${notes.length} post${notes.length===1?'':'s'}`:'';
    const wall=b.querySelector('#plWall');wall.innerHTML=notes.length?'':'<p class="meta">Nobody has posted yet. Be the first. It really helps the next person speak up.</p>';
    notes.slice(0,40).forEach(n=>{const id=n.id||n.t;const d=document.createElement('div');d.className='post';const when=new Date(n.t);d.innerHTML=`<p>${esc(n.text)}</p><div class="post-f"><span>${when.toLocaleDateString(undefined,{day:'numeric',month:'short'})}</span><button type="button" ${myAgree.includes(String(id))?'disabled':''}>Me too · ${cnt(id)}</button></div>`;
      d.querySelector('button').addEventListener('click',async e=>{e.target.disabled=true;myAgree.push(String(id));store.set('polAgree',myAgree);const item={act:p.id,kind:'agree',ref:id,t:Date.now()};try{await dbAppend('policy',item,80);}catch(err){localAppend('policyLocal',item);}render();});wall.appendChild(d);});};
  render();
  b.querySelector('#plGo').addEventListener('click',async()=>{const ta=b.querySelector('#plS');const v=ta.value.trim();const er=b.querySelector('#plE');if(v.length<4){er.textContent='Write a few words so others understand.';er.hidden=false;return;}er.hidden=true;
    const item={act:p.id,kind:'note',id:uid4(),text:v,t:Date.now()};let shared=true;try{await dbAppend('policy',item,80);}catch(e){shared=false;localAppend('policyLocal',item);}
    ta.value='';award(15,'Shared your view','policy-'+p.id);earnBadge('voice');track('policy_post',{id:p.id});toast(shared?'Posted to the wall. Thank you for speaking up.':'Saved on this device. It will show on your wall.');render();});}});};
/* the owner can download every response */
async function exportPolicy(){const docs=await (async()=>{try{const q=await DB.collection('policy').get();return q.docs.map(d=>d.data()||{});}catch(e){return [];}})();const rows=[['policy','type','question','answer_or_text','time']];
  docs.forEach(d=>(d.items||[]).forEach(x=>{const P=POLICIES.find(p=>p.id===x.act);const Q=POLICY_Q[x.act];rows.push([P?P.name:x.act,x.kind||'note',x.kind==='poll'&&Q?Q.poll[x.q][0]:'',x.kind==='poll'&&Q?Q.poll[x.q][1][x.a]:(x.text||(x.kind==='agree'?'agree with post':'')),new Date(x.t).toISOString()]);}));
  const csv=rows.map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'});let dl=null;try{dl=await window.claude.use('downloads');}catch(e){}if(dl){try{await dl.save({filename:'ymh-policy-responses.csv',data:blob});return;}catch(e){}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ymh-policy-responses.csv';a.click();}

/* ---------- videos that play inside the city ---------- */
const VIDEOS=(window.YMH_CONFIG&&YMH_CONFIG.videos||[]).filter(v=>v&&v.src);
const VID={el:null,tex:null,mesh:null,orig:null};
function playOnScreen(mesh,v,o){o=o||{};stopVideo();const el=document.createElement('video');el.src=v.src;el.crossOrigin='anonymous';el.playsInline=true;el.preload='auto';if(v.poster)el.poster=v.poster;
  const tex=new THREE.VideoTexture(el);tex.minFilter=THREE.LinearFilter;VID.el=el;VID.tex=tex;VID.mesh=mesh;VID.orig=mesh.material.map;mesh.material.map=tex;mesh.material.needsUpdate=true;el.play().catch(()=>{});if(AUD.L.pad&&AUD.L.pad.on)setLayer('pad',false);if(typeof radioStop==='function')radioStop();
  track('video_play',{id:v.id||v.title});
  openPanel({dock:true,title:v.title,eyebrow:o.eyebrow||'Now showing',color:o.color||'#c76b80',sub:v.desc||'',build:b=>{b.innerHTML=`<div class="vctl"><button class="btn primary" type="button" id="vP">Pause</button><input type="range" id="vS" min="0" max="1000" value="0" aria-label="Seek"><span class="meta" id="vT">0:00</span></div><div class="row" style="margin-top:8px"><label class="meta" for="vV">Volume</label><input type="range" id="vV" min="0" max="1" step="0.05" value="1" style="max-width:140px"><button class="btn" type="button" id="vF">Watch full screen</button><button class="btn ghost" type="button" id="vX">Stand up</button></div><p class="meta" id="vE" hidden>This video couldn't load. Check the file path in config.js.</p>`;
    const q=s=>b.querySelector(s);const fmt=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;let seeking=false;
    q('#vP').addEventListener('click',()=>{el.paused?el.play():el.pause();});q('#vV').addEventListener('input',e=>el.volume=+e.target.value);q('#vS').addEventListener('input',e=>{seeking=true;if(el.duration)el.currentTime=e.target.value/1000*el.duration;});q('#vS').addEventListener('change',()=>seeking=false);
    q('#vF').addEventListener('click',()=>fullVideo(el,v));q('#vX').addEventListener('click',closePanel);el.addEventListener('error',()=>{q('#vE').hidden=false;});
    let watched=0;const iv=setInterval(()=>{q('#vP').textContent=el.paused?'Play':'Pause';if(el.duration){if(!seeking)q('#vS').value=el.currentTime/el.duration*1000;q('#vT').textContent=`${fmt(el.currentTime)} / ${fmt(el.duration)}`;}if(!el.paused){watched++;if(watched===240)done(o.act||'theatre');}},250);
    el.addEventListener('ended',()=>{done(o.act||'theatre');award(15,'Watched '+v.title);track('video_complete',{id:v.id||v.title});});return ()=>{clearInterval(iv);};}});}
function stopVideo(){if(!VID.el)return;try{VID.el.pause();}catch(e){}if(VID.mesh&&VID.orig){VID.mesh.material.map=VID.orig;VID.mesh.material.needsUpdate=true;}VID.el.removeAttribute('src');VID.el.load();VID.el=null;if(VID.tex)VID.tex.dispose();VID.tex=null;}
function fullVideo(el,v){let ov=$('vidOv');if(!ov){ov=document.createElement('div');ov.id='vidOv';ov.innerHTML='<div class="vid-card"><button class="bk-x" type="button" aria-label="Close">×</button><div class="vid-slot"></div><p class="vid-t"></p></div>';document.body.appendChild(ov);}
  ov.hidden=false;ov.querySelector('.vid-t').textContent=v.title;const slot=ov.querySelector('.vid-slot');slot.innerHTML='';el.controls=true;slot.appendChild(el);const close=()=>{el.controls=false;ov.hidden=true;document.body.appendChild(el);el.style.display='none';};ov.querySelector('.bk-x').onclick=close;}
function screenMesh(w,tex){let m=null;w.scene.traverse(o=>{if(o.isMesh&&o.material&&o.material.map===tex)m=o;});return m;}
{const _sf=sitFilm;sitFilm=function(w,x,z,ax){if(!VIDEOS.filter(v=>v.where!=='hall').length){_sf(w,x,z,ax);return;}
  openPanel({title:'What would you like to watch?',eyebrow:'YMH Theatre',color:'#c76b80',sub:'Take your seat, the lights will dim.',build:b=>{b.innerHTML=`<div class="goto" id="vL"></div>`;const L=b.querySelector('#vL');
    const add=(t,s,fn)=>{const x=document.createElement('button');x.type='button';x.innerHTML=`<i style="background:#c76b80"></i><span><b>${esc(t)}</b><br><small>${esc(s)}</small></span>`;x.addEventListener('click',()=>{closePanel();fn();});L.appendChild(x);};
    VIDEOS.filter(v=>v.where!=='hall').forEach(v=>add(v.title,v.desc||'Film',()=>{const scr=screenMesh(THEATRE_W,FILM.tex);startAction({x,z,rot:Math.PI,y:-0.21,pose:POSE.sit,camOff:Math.PI,dist:5.2,pitch:0.12,exit:{x:ax,z:z+0.2},onEnd:()=>{stopVideo();FILM.playing=false;}});FILM.playing=false;playOnScreen(scr,v,{act:'theatre'});THEATRE_W.hemi.intensity=0.22;}));
    add('Small Steps','An 80-second animated short',()=>_sf(w,x,z,ax));}});};}
{const _ex=THEATRE_W.onExit;THEATRE_W.onExit=function(){if(_ex)_ex();stopVideo();};}

/* YMH Week hall: play the highlights inside the hall, or embed them */
{const hb=HALL_W.build;HALL_W.build=w=>{hb(w);let scr=null;w.scene.traverse(o=>{if(o.isMesh&&Math.abs(o.position.z+12.55)<0.05&&Math.abs(o.position.y-5)<0.05&&o.geometry.parameters&&o.geometry.parameters.width===12)scr=o;});
  const sp=SPOTS.find(s=>s.label&&s.label.startsWith('Watch last year'));if(!sp)return;
  sp.run=()=>{award(5,'Watched YMH Week highlights','ymhvid');done('ymhweek');const v=VIDEOS.find(q=>q.where==='hall');if(v&&scr){playOnScreen(scr,v,{eyebrow:'YMH Week 2027',color:'#d97a68',act:'ymhweek'});return;}
    const did=(YMH_VIDEO.match(/\/d\/([\w-]+)/)||[])[1];const emb=did?`https://drive.google.com/file/d/${did}/preview`:YMH_VIDEO;openPanel({wide:true,title:'YMH Week 2026 highlights',eyebrow:'Youth Mental Health Week',color:'#d97a68',sub:'2027 is coming soon. Here\'s a look at last year.',build:b=>{b.innerHTML=`<div class="yt"><iframe src="${emb}" title="YMH Week 2026 highlights" allow="autoplay; encrypted-media; fullscreen"></iframe></div><p class="meta" style="margin-top:8px">If the video doesn't load here, <a href="${YMH_VIDEO}" target="_blank" rel="noopener">open it on Google Drive</a>.</p>`;}});track('video_play',{id:'ymhweek-embed'});};
  const _ex=w.onExit;w.onExit=function(){if(_ex)_ex();stopVideo();};};}

/* Kiran: a quick emoji check-in, nothing more */
function kiranCheckIn(){const F=[['😄','Great'],['🙂','Okay'],['😐','Meh'],['😔','Low'],['😣','Stressed']];
  openPanel({title:'How are you feeling?',eyebrow:'Support Booth · Kiran',color:Z.help.color,sub:'Tap one. It stays on this device.',build:b=>{
    b.innerHTML=`<div class="moods" style="grid-template-columns:repeat(5,minmax(0,1fr))">${F.map(([e,t],i)=>`<button type="button" data-i="${i}"><span>${e}</span>${t}</button>`).join('')}</div><p class="lead" id="kcR" style="margin-top:14px" hidden></p><div class="row" id="kcB" hidden><button class="btn primary" type="button" id="kcH">See who you can reach</button><button class="btn" type="button" id="kcX">Done</button></div>`;
    b.querySelectorAll('[data-i]').forEach(x=>x.addEventListener('click',()=>{b.querySelectorAll('[data-i]').forEach(y=>y.setAttribute('aria-pressed',String(y===x)));const i=+x.dataset.i;
      const r=b.querySelector('#kcR');r.hidden=false;r.textContent=i<2?'Glad to hear it. Thanks for checking in.':i===2?'Thanks for checking in. Some days are just like that.':'Thanks for telling me. If you\'d like to talk to someone trained, free helplines are on the wall board.';
      b.querySelector('#kcB').hidden=false;b.querySelector('#kcH').hidden=i<2;track('activity',{id:'kiran-checkin',mood:F[i][1]});done('help');}));
    b.querySelector('#kcH').addEventListener('click',()=>{closePanel();helpPanel(false);});b.querySelector('#kcX').addEventListener('click',closePanel);}});}
